<?php
namespace Tests\Feature;
use App\Models\Products;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Hash;use Tests\TestCase;
class SalesOrderTest extends TestCase {use RefreshDatabase;private function manager(){return User::create(['name'=>'Manager','email'=>'sales-manager@example.test','password'=>Hash::make('password'),'role'=>'manager','is_active'=>true]);}public function test_sales_order_deducts_stock_and_creates_ledger_entry():void{$user=$this->manager();$product=Products::create(['product_name'=>'Laptop','sku'=>'LAP-001','product_price'=>1000000,'cost_price'=>700000,'category'=>'Electronics','stock_quantity'=>10,'reorder_level'=>2,'is_active'=>true]);$response=$this->actingAs($user)->post(route('orders.store'),['order_date'=>now()->toDateString(),'items'=>[['product_id'=>$product->id,'quantity'=>3]]]);$response->assertRedirect();$this->assertDatabaseHas('products',['id'=>$product->id,'stock_quantity'=>7]);$this->assertDatabaseHas('order_items',['product_id'=>$product->id,'quantity'=>3]);$this->assertDatabaseHas('stock_movements',['product_id'=>$product->id,'type'=>'STOCK_OUT','quantity'=>3,'balance_before'=>10,'balance_after'=>7]);}public function test_order_cannot_sell_more_than_available_stock():void{$user=$this->manager();$product=Products::create(['product_name'=>'Keyboard','sku'=>'KEY-001','product_price'=>50000,'cost_price'=>30000,'category'=>'Electronics','stock_quantity'=>2,'reorder_level'=>1,'is_active'=>true]);$response=$this->actingAs($user)->post(route('orders.store'),['order_date'=>now()->toDateString(),'items'=>[['product_id'=>$product->id,'quantity'=>3]]]);$response->assertStatus(422);$this->assertDatabaseCount('orders',0);$this->assertDatabaseHas('products',['id'=>$product->id,'stock_quantity'=>2]);}}
